INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (19, 'Браслет', 'Продаю браслети різного типу. Той що на фото створений спеціально на заказ, час створення - два дні. Форма браслету будь-яка. Якщо цікавить - напишіть в особисті, або у вайбер або телеграм', '900.0', 1, 2, '/uploads/2dcc5032-8008-4df1-ab69-5c08f0e3e126_mbss23-153647-mod-1.png', '2026-11-03 12:17:09', 'Нове', 1, 'Власівка', 'Reserved', 0, 6) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (20, 'Apple iPhone 15 Pro 128GB Black Titanium', 'Телефон в ідеальному стані, без подряпин чи сколів. Акумулятор 98%. Повний заводський комплект: коробка, рідний кабель Type-C, документація. Працює з усіма операторами. Захисне скло у подарунок.', '28500', 12, 1, '/uploads/3b0c9091-42d4-493c-803b-7c50952e0dc1_Phone.jpg', '2026-11-04 11:13:37', 'Вживане', 1, 'Кременчук', 'Active', 1, 152) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (21, 'Бездротові навушники Sony WH-1000XM4 з шумозаглушенням', 'Найкраще активне шумозаглушення на ринку. Звук кришталево чистий. Батарея тримає до 30 годин. У комплекті чохол, аудіокабель та зарядний дріт. Використовувались обережно для навчання.', '5800', 12, 1, '/uploads/0616f8b8-24a1-4fe8-93f3-207214872194_sample.png', '2026-11-04 08:13:37', 'Вживане', 1, 'Кременчук', 'Active', 0, 92) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (22, 'Ігрова консоль Sony PlayStation 5 Slim 1TB', 'Версія з дисководом. Купувалась офіційно півроку тому, стан нової консолі. В комплекті оригінальний геймпад DualSense, HDMI кабель, підставка та коробка. Працює безшумно.', '18900', 14, 1, '/uploads/dc5b21d9-11e8-4428-b885-06ca38f2870c_sample.png', '2026-11-04 05:13:37', 'Вживане', 1, 'Київ', 'Active', 1, 217) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (23, 'Планшет Apple iPad Air M1 64GB Space Gray', 'Потужний процесор Apple M1, підходить для дизайну, малювання та монтажу відео. Екран Liquid Retina в ідеалі, завжди під плівкою. Комплект з коробкою та зарядним блоком 20W.', '16200', 13, 1, '/uploads/2dcc5032-8008-4df1-ab69-5c08f0e3e126_mbss23-153647-mod-1.png', '2026-11-04 02:13:37', 'Вживане', 1, 'Кременчук', 'Active', 0, 97) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (24, 'Механічна бездротова клавіатура Keychron K2 RGB (Gateron Brown)', 'Підтримує Bluetooth та підключення через Type-C. Сумісна з Mac та Windows. Тактильні світчі Gateron Brown для комфортного набору тексту та ігор. Повний комплект зі змінними кейкапами.', '2400', 14, 1, '/uploads/0b53c62d-80a7-45a9-8274-d50070773238_image.webp', '2026-11-03 23:13:37', 'Нове', 1, 'Полтава', 'Active', 1, 70) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (25, 'Монітор 27" Dell UltraSharp 4K IPS (U2720Q)', 'Професійний 4K монітор з точним калібруванням кольору (99% sRGB, 95% DCI-P3). Підключення по USB-C з зарядкою ноутбука (90W). Вбудований USB-хаб. Стан ідеальний, битих пікселів немає.', '9800', 14, 1, '/uploads/0616f8b8-24a1-4fe8-93f3-207214872194_sample.png', '2026-11-03 20:13:37', 'Вживане', 1, 'Кременчук', 'Active', 0, 112) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (26, 'Портативна колонка JBL Charge 5 Squad (Камуфляж)', 'Оригінал JBL. Потужний басовитий звук, вологозахист IP67. Батарея тримає до 20 годин музики, функція повербанка для зарядки телефона. Стан чудовий, грає гучно.', '3200', 16, 1, '/uploads/dc5b21d9-11e8-4428-b885-06ca38f2870c_sample.png', '2026-11-03 17:13:37', 'Вживане', 1, 'Кременчук', 'Active', 0, 79) ON CONFLICT DO NOTHING;
INSERT INTO "Listings" ("Id", "Title", "Description", "Price", "SellerId", "CategoryId", "ImageUrl", "CreatedAt", "Condition", "IsShippingAvailable", "Location", "Status", "IsFeatured", "ViewsCount") VALUES (27, 'Оригінальні кросівки Nike Air Jordan 1 Low (43 розмір)', 'Купувалися на офіційному європейському сайті. Носив буквально 2-3 рази, не підійшов розмір повноти стопи. Стан підошви та шкіри 10/10. Довжина устілки 27.5 см.', '3100', 12, 2, '/uploads/1bf1e407-5e47-49ea-b649-25cfb8206eac.jpg', '2026-11-03 14:13:37', 'Вживане', 1, 'Кременчук', 'Active', 1, 90) ON CONFLICT DO NOTHING;
